import { Box, Chip, Grid, Typography } from '@mui/material';
import React from 'react';
import { appColors } from '../../../../theme/appColors';
import { useSelector } from 'react-redux';
import { selectBasketItems } from '../../store/BasketSelector';
import { getPriceFormatWithoutCurrency } from '../../../../core/utils';
import { BasketItem } from '../../store/BasketSlice';
import AddPurchase from '../AddPurchase';

const profileLabel = (name: string, fontSize?: number) => (
  <Typography
    align="left"
    sx={{
      fontSize: fontSize ?? 13,
      fontWeight: 500,
      color: appColors.royalBlue[100],
      lineHeight: 1.2,
    }}
  >
    {name}
  </Typography>
);

const profileValue = (val: string, fontSize?: number) => (
  <Typography
    align="right"
    sx={{
      fontSize: fontSize ?? 13,
      color: appColors.royalBlue[80],
      fontVariantNumeric: 'tabular-nums',
    }}
  >
    {val}
  </Typography>
);

const PurchaseBasketItems = () => {
  const selectItem = useSelector(selectBasketItems);
  const [editOpen, setEditOpen] = React.useState(false);
  const [editItem, setEditItem] = React.useState<BasketItem | undefined>();

  if (selectItem.length === 0) {
    return (
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          height: '100%',
          opacity: 0.35,
          gap: 1,
          py: 4,
        }}
      >
        <Typography sx={{ fontSize: 13, color: appColors.royalBlue[60] }}>
          No items added yet
        </Typography>
      </Box>
    );
  }

  return (
    <Box sx={{ p: '4px 8px 0 8px' }}>
      {selectItem
        .slice()
        .reverse()
        .map((item) => (
          <Grid
            alignItems="center"
            container
            key={item.id}
            onClick={() => {
              setEditItem(item);
              setEditOpen(true);
            }}
            spacing={1}
            sx={{
              py: '6px',
              px: '4px',
              cursor: 'pointer',
              borderBottom: `1px solid ${appColors.darkGray[10]}`,
              '&:last-child': { borderBottom: 'none' },
              flexWrap: 'nowrap',
              borderRadius: '6px',
              transition: 'background 0.15s ease',
              '&:hover': { backgroundColor: appColors.reflexBlue[10] },
            }}
          >
            <Grid item md={3} xs={3}>
              {profileLabel(item.name)}
            </Grid>
            <Grid item md={2} xs={2}>
              <Box
                sx={{
                  alignItems: 'flex-end',
                  display: 'flex',
                  flexDirection: 'column',
                  gap: 0.4,
                }}
              >
                <Chip
                  label={item.quanity}
                  size="small"
                  sx={{
                    height: 20,
                    fontSize: 11,
                    fontWeight: 700,
                    backgroundColor: appColors.reflexBlue[100],
                    color: appColors.white,
                    '& .MuiChip-label': { px: '6px' },
                  }}
                />
                {item.freeQty > 0 && (
                  <Chip
                    label={`+${item.freeQty} free`}
                    size="small"
                    sx={{
                      backgroundColor: '#DCFCE7',
                      color: '#166534',
                      fontSize: 9,
                      fontWeight: 700,
                      height: 17,
                      '& .MuiChip-label': { px: '5px' },
                    }}
                  />
                )}
              </Box>
            </Grid>
            <Grid item md={2} xs={2}>
              {profileValue(getPriceFormatWithoutCurrency(item.price ?? 0).toString())}
            </Grid>
            <Grid item md={2} xs={2}>
              {profileValue(
                `${getPriceFormatWithoutCurrency(item.discount ?? 0)}${item.isDiscountPercentage ? '%' : ''}`,
              )}
            </Grid>
            <Grid item md={1.5} xs={1.5}>
              {profileValue(getPriceFormatWithoutCurrency(item.cost ?? 0).toString())}
            </Grid>
            <Grid item md={1.5} xs={1.5}>
              {profileValue(
                getPriceFormatWithoutCurrency(
                  item.quanity * (item.price ?? 0),
                ).toString(),
              )}
            </Grid>
          </Grid>
        ))}
      {editOpen && editItem && (
        <AddPurchase
          handleCloseDialog={() => {
            setEditOpen(false);
            setEditItem(undefined);
          }}
          item={editItem}
          openModel={editOpen}
          title="Edit Purchase Item"
        />
      )}
    </Box>
  );
};

export default React.memo(PurchaseBasketItems);
