import AnimatedPage from '../../layouts/AnimatedPage';
import { Box, Grid } from '@mui/material';
import PurchaseLeft from './components/PurchaseLeft/Index';
import PurchaseRight from './components/PurchaseRight/Index';
import React, { useEffect } from 'react';

const Purchase = () => {
  useEffect(() => {
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = prev;
    };
  }, []);

  return (
    <AnimatedPage>
      <Box
        sx={{
          height: '100vh',
          overflow: 'hidden',
        }}
      >
        <Grid
          container
          spacing={1}
        >
          <Grid
            item
            md={4}
            sm={4}
            xs={12}
          >
            <PurchaseLeft />
          </Grid>
          <Grid
            item
            md={8}
            sm={8}
            xs={12}
          >
            <PurchaseRight />
          </Grid>
        </Grid>
      </Box>
    </AnimatedPage>
  );
};

export default Purchase;
