import { Box, Grid, Typography } from '@mui/material';
import React from 'react';
import SupplierSearch from './SupplierSearch';
import { appColors, HEADER_GRADIENT } from '../../../../theme/appColors';
import PurchaseSummary from './Summary';
import PurchaseBasketItems from './BasketItems';

const colHeader = (label: string, align: 'left' | 'right' = 'right') => (
  <Typography
    align={align}
    sx={{
      textTransform: 'uppercase',
      fontWeight: 700,
      fontSize: 10,
      color: 'rgba(255,255,255,0.8)',
      letterSpacing: '0.5px',
    }}
  >
    {label}
  </Typography>
);

const PurchaseLeft = () => {
  return (
    <Box
      sx={{
        position: 'fixed',
        left: 4,
        width: '32%',
        height: 'calc(100vh - 96px)',
        display: 'flex',
        flexDirection: 'column',
        zIndex: 10,
        borderRadius: '12px',
        overflow: 'hidden',
        boxShadow: '0 4px 24px rgba(0,20,137,0.14)',
        backgroundColor: appColors.white,
      }}
    >
      {/* Supplier & product search */}
      <Box
        sx={{
          p: '10px 10px 8px 10px',
          backgroundColor: appColors.white,
          borderBottom: `1px solid ${appColors.darkGray[10]}`,
        }}
      >
        <SupplierSearch />
      </Box>

      {/* Column headers */}
      <Box
        sx={{
          background: HEADER_GRADIENT,
          px: '12px',
          py: '8px',
        }}
      >
        <Grid
          container
          flexWrap="nowrap"
          spacing={1}
        >
          <Grid item md={3} xs={3}>{colHeader('Item', 'left')}</Grid>
          <Grid item md={2} xs={2}>{colHeader('Qty / Free')}</Grid>
          <Grid item md={2} xs={2}>{colHeader('Price')}</Grid>
          <Grid item md={2} xs={2}>{colHeader('Discount')}</Grid>
          <Grid item md={1.5} xs={1.5}>{colHeader('Cost')}</Grid>
          <Grid item md={1.5} xs={1.5}>{colHeader('Amount')}</Grid>
        </Grid>
      </Box>

      {/* Basket items — scrollable */}
      <Box
        sx={{
          flex: 1,
          overflowY: 'auto',
          backgroundColor: appColors.white,
          scrollbarWidth: 'thin',
          '&::-webkit-scrollbar': { width: '3px' },
          '&::-webkit-scrollbar-thumb': {
            backgroundColor: '#94a3b8',
            borderRadius: '2px',
          },
        }}
      >
        <PurchaseBasketItems />
      </Box>

      {/* Summary footer */}
      <PurchaseSummary />
    </Box>
  );
};

export default React.memo(PurchaseLeft);
